/** Corpo curado do aspecto ponto×planeta + tom. null se não houver (cai no composer). */
export function pointAspectBody(pointKey: string, planetKey: string, tone: string, lang: string): string | null {
  const key = [String(pointKey || '').toLowerCase(), String(planetKey || '').toLowerCase()].sort().join('+')
  const t = (tone === 'harmonioso' || tone === 'tenso' || tone === 'neutro') ? tone as Tone : 'neutro'
  const r = READINGS[key]?.[t]
  return r ? (r[L(lang)] || r['pt-BR']) : null
}
